          toolSetSetting: "\u041C\u0435\u043D\u044F\u044E \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0443\u2026",
          toolMediaStatus: "\u0421\u043C\u043E\u0442\u0440\u044E, \u0447\u0442\u043E \u0438\u0433\u0440\u0430\u0435\u0442\u2026",
          toolMediaCommand: "\u0423\u043F\u0440\u0430\u0432\u043B\u044F\u044E \u043F\u043B\u0435\u0435\u0440\u043E\u043C\u2026",
